const PR30=[{label:"Lỗi: tràn số khi cộng bình phương",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int a = 100000, b = 100000;\n    int sai = a * a + b * b;                // SAI: 2·10^10 vượt int\n    long long dung = 1LL * a * a + 1LL * b * b;\n    cout << sai << \" \" << dung << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","sai","dung"]}]},{label:"Lỗi: chia nguyên",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int tong = 7, n = 2;\n    double sai = tong / n;                  // SAI: 7 / 2 = 3 (chia nguyên) rồi mới đổi sang 3.0\n    double dung = (double)tong / n;\n    cout << sai << \" \" << dung << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["tong","n","sai","dung"]}]},{label:"Lỗi: quên đặt lại giữa các test",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int T = 2;\n    vector<vector<int>> test = {{1, 2, 3}, {4, 5}};\n    long long tong = 0;                     // SAI: khai báo ngoài vòng lặp test\n    for (int t = 0; t < T; t++) {\n        for (int x : test[t]) tong += x;\n        cout << tong << \"\\n\";               // đúng phải là 6 rồi 9\n    }\n    return 0;\n}",viz:[{type:"vars",names:["t","tong"]}]}];
